context=ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER);context.load_cert_chain('server.crt','server.key')

def exact(c,n):
    data=b''
    while len(data)<n:
        part=c.recv(n-len(data))
        if not part:raise EOFError('missing input bytes')
        data+=part
    return data
@contextlib.contextmanager
def fixture(payload,allow_verify_failure=False):
    listener=socket.socket();listener.bind(('127.0.0.1',0));listener.listen(1);listener.settimeout(2)
    endpoint=listener.getsockname();stop=threading.Event();seen=[];errors=[];connections=[]
    def worker():
        try:
            raw,_=listener.accept();connections.append(raw);raw.settimeout(2)
            with raw:
                try:secure=context.wrap_socket(raw,server_side=True)
                except ssl.SSLError:
                    if allow_verify_failure:return
                    raise
                connections.append(secure)
                with secure:
                    if payload is None:received=b''
                    else:
                        size=struct.unpack('!I',exact(secure,4))[0];received=exact(secure,size);assert received==payload
                    seen.append(received)
                    secure.sendall(b'\xffreply:'+received[::-1]);plain=secure.unwrap();plain.close()
        except OSError as exc:
            if not stop.is_set():errors.append(repr(exc))
        except Exception as exc:errors.append(repr(exc))
        finally:listener.close()
    thread=threading.Thread(target=worker);thread.start()
    try:yield endpoint[1],seen
    finally:
        stop.set();listener.close()
        for conn in connections:
            try:conn.shutdown(socket.SHUT_RDWR)
            except OSError:pass
        thread.join(3);assert not thread.is_alive();assert not errors,errors
for payload in [b'',b'plain text\n',secrets.token_bytes(32768),b'\0\xff\r\nEND']:
    with fixture(payload) as (port,seen):
        run=subprocess.run(['bash','tunnel.sh',str(port),'dns.lab.test','ca.crt'],input=struct.pack('!I',len(payload))+payload,capture_output=True,timeout=4)
        assert run.returncode==0 and run.stdout==b'\xffreply:'+payload[::-1],(run.returncode,run.stdout[:100],run.stderr[-300:])
    assert seen==[payload]
